import { defineStore } from 'pinia'

interface AppNotification {
  id:        string
  type:      string
  title:     string
  message:   string
  read:      boolean
  orderId?:  string | null
  createdAt: string
}

export const useUIStore = defineStore('ui', {
  state: () => ({
    sidebarCollapsed:   false,
    mobileSidebarOpen:  false,
    notifications:      [] as AppNotification[],
    notifsLoaded:       false,
  }),
  getters: {
    unreadCount: (s) => s.notifications.filter(n => !n.read).length,
  },
  actions: {
    toggleSidebar()      { this.sidebarCollapsed  = !this.sidebarCollapsed },
    openMobileSidebar()  { this.mobileSidebarOpen = true },
    closeMobileSidebar() { this.mobileSidebarOpen = false },

    async fetchNotifications() {
      try {
        const res = await $fetch<{ notifications: AppNotification[]; unreadCount: number }>(
          '/api/notifications',
        )
        this.notifications = res.notifications
        this.notifsLoaded  = true
      } catch { /* silencioso */ }
    },

    async markRead(id: string) {
      const n = this.notifications.find(n => n.id === id)
      if (n) n.read = true
      try { await $fetch(`/api/notifications/${id}/read`, { method: 'POST' }) } catch { /* ok */ }
    },

    async markAllRead() {
      this.notifications.forEach(n => { n.read = true })
      try { await $fetch('/api/notifications/read-all', { method: 'POST' }) } catch { /* ok */ }
    },
  },
})
<template>
  <aside :style="sidebarStyle" class="no-scrollbar">

    <!-- Logo -->
    <div style="height:60px;display:flex;align-items:center;padding:0 16px;border-bottom:1px solid rgba(255,255,255,0.06);flex-shrink:0;gap:10px;overflow:hidden;">
      <div style="width:30px;height:30px;border-radius:8px;overflow:hidden;flex-shrink:0;box-shadow:0 0 14px rgba(14,165,233,0.35);">
        <img src="/logosieeg.jpg" alt="SIEEG" style="width:100%;height:100%;object-fit:cover;" />
      </div>
      <div v-if="!collapsed || isMobile" style="overflow:hidden;white-space:nowrap;transition:opacity 0.2s;flex:1;">
        <div style="font-size:13px;font-weight:800;color:#E2EAF4;line-height:1;letter-spacing:-0.3px;">SIEEG</div>
        <div style="font-size:9px;color:rgba(100,118,142,0.7);font-weight:500;letter-spacing:0.8px;margin-top:2px;">INTEGRADORES</div>
      </div>
      <!-- Close button on mobile -->
      <button v-if="isMobile" @click="ui.closeMobileSidebar()"
        style="width:30px;height:30px;border-radius:8px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;margin-left:auto;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="rgba(123,146,176,0.8)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
          <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </button>
    </div>

    <!-- Nav -->
    <nav style="flex:1;padding:8px 6px;overflow-y:auto;overflow-x:hidden;" class="no-scrollbar">
      <div v-if="!collapsed || isMobile" style="font-size:9px;font-weight:600;color:rgba(100,118,142,0.8);text-transform:uppercase;letter-spacing:1.2px;padding:4px 10px 8px;user-select:none;">
        Navegación
      </div>

      <NuxtLink v-for="item in navItems" :key="item.href" :to="item.href" style="text-decoration:none;display:block;margin-bottom:1px;"
        @click="isMobile && ui.closeMobileSidebar()">
        <div :style="linkStyle(item.href)" :title="collapsed && !isMobile ? item.label : undefined"
          @mouseenter="e => onHover(e, item.href, true)"
          @mouseleave="e => onHover(e, item.href, false)">

          <!-- Indicador activo -->
          <div v-if="isActive(item.href)" style="position:absolute;left:0;top:50%;transform:translateY(-50%);width:3px;height:18px;border-radius:0 3px 3px 0;background:#0EA5E9;box-shadow:0 0 8px rgba(14,165,233,0.7);" />

          <!-- Icono SVG inline -->
          <svg :width="15" :height="15" viewBox="0 0 24 24" fill="none"
            :stroke="isActive(item.href) ? '#7DD3FC' : 'rgba(100,118,142,0.75)'"
            :stroke-width="isActive(item.href) ? 2.2 : 1.8"
            stroke-linecap="round" stroke-linejoin="round"
            style="flex-shrink:0;" v-html="item.svg" />

          <!-- Label -->
          <span v-if="!collapsed || isMobile" :style="{ fontSize:'12.5px', fontWeight:isActive(item.href)?600:500, color:isActive(item.href)?'#E2EAF4':'rgba(100,118,142,0.8)', whiteSpace:'nowrap', flex:1, overflow:'hidden', textOverflow:'ellipsis', transition:'opacity 0.15s' }">
            {{ item.label }}
          </span>

          <!-- Badge carrito -->
          <div v-if="item.cart && cartCount > 0" :style="badgeStyle">
            {{ cartCount }}
          </div>
        </div>
      </NuxtLink>
    </nav>

    <!-- Botón colapsar (solo desktop) -->
    <button v-if="!isMobile" @click="ui.toggleSidebar()"
      style="position:absolute;right:-11px;top:72px;width:22px;height:22px;border-radius:50%;background:#0C1A2E;border:1px solid rgba(255,255,255,0.12);display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:30;box-shadow:0 2px 8px rgba(0,0,0,0.4);padding:0;">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="rgba(123,146,176,0.8)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
        <path v-if="!collapsed" d="m15 18-6-6 6-6"/>
        <path v-else            d="m9 18 6-6-6-6"/>
      </svg>
    </button>
  </aside>
</template>

<script setup lang="ts">
const route = useRoute()
const ui    = useUIStore()
const cart  = useCartStore()
const auth  = useAuthStore()
const { isMobile } = useBreakpoint()

const collapsed  = computed(() => ui.sidebarCollapsed)
const cartCount  = computed(() => cart.count)

const ALL_NAV = [
  {
    href: '/dashboard', label: 'Dashboard', roles: ['admin', 'approver', 'viewer'],
    svg: '<rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/>',
  },
  {
    href: '/catalog', label: 'Catálogo', roles: null,
    svg: '<path d="M16.5 9.4 7.55 4.24"/><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.29 7 12 12 20.71 7"/><line x1="12" x2="12" y1="22" y2="12"/>',
  },
  {
    href: '/cart', label: 'Carrito', cart: true, roles: null,
    svg: '<circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/>',
  },
  {
    href: '/orders', label: 'Órdenes', roles: null,
    svg: '<rect width="8" height="4" x="8" y="2" rx="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><path d="M12 11h4"/><path d="M12 16h4"/><path d="M8 11h.01"/><path d="M8 16h.01"/>',
  },
  {
    href: '/users', label: 'Usuarios', roles: ['admin'],
    svg: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
  },
  {
    href: '/admin', label: 'Precios', roles: ['admin'],
    svg: '<path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/>',
  },
  {
    href: '/fiscal', label: 'Datos Fiscales', roles: ['admin'],
    svg: '<rect width="16" height="20" x="4" y="2" rx="2"/><path d="M8 10h8"/><path d="M8 14h5"/><path d="M8 6h8"/>',
  },
  {
    href: '/facturas', label: 'Facturación', roles: ['admin'],
    svg: '<path d="M4 2v20l2-1 2 1 2-1 2 1 2-1 2 1 2-1 2 1V2l-2 1-2-1-2 1-2-1-2 1-2-1-2 1Z"/><path d="M16 8H8"/><path d="M16 12H8"/><path d="M12 16H8"/>',
  },
  {
    href: '/perfil', label: 'Mi Perfil', roles: ['buyer', 'approver', 'viewer'],
    svg: '<circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/>',
  },
]

const navItems = computed(() => {
  const role = auth.user?.role ?? ''
  return ALL_NAV.filter(item => !item.roles || item.roles.includes(role))
})

const sidebarStyle = computed(() => {
  if (isMobile.value) {
    return {
      position:   'fixed',
      top:        '0',
      left:       '0',
      height:     '100%',
      width:      '260px',
      display:    'flex',
      flexDirection: 'column',
      background: 'rgba(3,9,20,0.99)',
      borderRight: '1px solid rgba(255,255,255,0.07)',
      zIndex:     '200',
      overflow:   'visible',
      transform:  ui.mobileSidebarOpen ? 'translateX(0)' : 'translateX(-100%)',
      transition: 'transform 0.28s cubic-bezier(0.4,0,0.2,1)',
    }
  }
  return {
    width:       collapsed.value ? '64px' : '220px',
    transition:  'width 0.28s cubic-bezier(0.4,0,0.2,1)',
    flexShrink:  '0',
    height:      '100%',
    display:     'flex',
    flexDirection: 'column',
    background:  'rgba(3,9,20,0.98)',
    borderRight: '1px solid rgba(255,255,255,0.07)',
    position:    'relative',
    zIndex:      '20',
    overflow:    'visible',
  }
})

function isActive(href: string) {
  return href === '/dashboard' ? route.path === href : route.path.startsWith(href)
}

function linkStyle(href: string) {
  const active = isActive(href)
  const expand = !collapsed.value || isMobile.value
  return {
    display: 'flex',
    alignItems: 'center',
    gap: '9px',
    height: '36px',
    padding: expand ? '0 10px' : '0',
    justifyContent: expand ? 'flex-start' : 'center',
    borderRadius: '9px',
    position: 'relative',
    cursor: 'pointer',
    background: active ? 'rgba(14,165,233,0.10)' : 'transparent',
    border: `1px solid ${active ? 'rgba(14,165,233,0.18)' : 'transparent'}`,
    transition: 'background 0.15s, border-color 0.15s',
    overflow: 'hidden',
  }
}

function onHover(e: MouseEvent, href: string, entering: boolean) {
  if (!isActive(href)) {
    (e.currentTarget as HTMLElement).style.background = entering ? 'rgba(255,255,255,0.04)' : 'transparent'
  }
}

const badgeStyle = computed(() => ({
  position:   (!collapsed.value || isMobile.value) ? 'static' : 'absolute',
  top:        (!collapsed.value || isMobile.value) ? undefined : '3px',
  right:      (!collapsed.value || isMobile.value) ? undefined : '3px',
  minWidth:   '17px', height: '17px', borderRadius: '9px',
  background: '#0EA5E9', display: 'flex', alignItems: 'center',
  justifyContent: 'center', fontSize: '9px', fontWeight: 700,
  color: 'white', padding: '0 4px', flexShrink: 0,
}))
</script>
<template>
  <header :style="{ height:'60px', display:'flex', alignItems:'center', padding: isMobile ? '0 16px' : '0 24px', borderBottom:'1px solid rgba(255,255,255,0.06)', background:'rgba(4,11,24,0.95)', backdropFilter:'blur(12px)', flexShrink:0, gap:'12px', position:'sticky', top:0, zIndex:10, fontFamily:`'Inter',system-ui,sans-serif` }">

    <!-- Hamburger (solo mobile) -->
    <button v-if="isMobile" @click="ui.openMobileSidebar()"
      style="width:36px;height:36px;border-radius:10px;background:transparent;border:1px solid transparent;display:flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;"
      @mouseenter="e => (e.currentTarget as HTMLElement).style.background='rgba(255,255,255,0.06)'"
      @mouseleave="e => (e.currentTarget as HTMLElement).style.background='transparent'">
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="rgba(123,146,176,0.9)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/>
      </svg>
    </button>

    <div style="margin-left:auto;display:flex;align-items:center;gap:4px;">

      <!-- Notificaciones -->
      <div style="position:relative;">
        <button @click="notifOpen=!notifOpen; userOpen=false"
          :style="{ width:'36px', height:'36px', borderRadius:'10px', background:notifOpen?'rgba(255,255,255,0.08)':'transparent', border:'1px solid transparent', display:'flex', alignItems:'center', justifyContent:'center', cursor:'pointer', position:'relative' }"
          @mouseenter="e => (e.currentTarget as HTMLElement).style.background='rgba(255,255,255,0.06)'"
          @mouseleave="e => { if(!notifOpen)(e.currentTarget as HTMLElement).style.background='transparent' }">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="rgba(123,146,176,0.9)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>
          </svg>
          <div v-if="ui.unreadCount > 0" style="position:absolute;top:5px;right:5px;width:16px;height:16px;border-radius:50%;background:#0EA5E9;font-size:9px;font-weight:700;color:white;display:flex;align-items:center;justify-content:center;">
            {{ ui.unreadCount }}
          </div>
        </button>

        <Transition name="dropdown">
          <div v-if="notifOpen" :style="{ position:'absolute', right:0, top:'44px', width: isMobile ? 'calc(100vw - 32px)' : '300px', maxWidth:'300px', background:'#0C1A2E', border:'1px solid rgba(255,255,255,0.1)', borderRadius:'14px', boxShadow:'0 16px 48px rgba(0,0,0,0.6)', overflow:'hidden', zIndex:50 }">
            <div style="display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid rgba(255,255,255,0.07);">
              <span style="font-size:13px;font-weight:600;color:#E2EAF4;">Notificaciones</span>
              <button v-if="ui.unreadCount > 0" @click="ui.markAllRead()" style="font-size:11px;color:#7DD3FC;background:none;border:none;cursor:pointer;font-weight:500;">Marcar leídas</button>
            </div>
            <div style="max-height:280px;overflow-y:auto;">
              <div v-for="n in ui.notifications" :key="n.id" @click="ui.markRead(n.id)"
                :style="{ display:'flex', gap:'10px', padding:'11px 14px', borderBottom:'1px solid rgba(255,255,255,0.04)', cursor:'pointer', background:!n.read?'rgba(14,165,233,0.04)':'transparent' }"
                @mouseenter="e => (e.currentTarget as HTMLElement).style.background='rgba(255,255,255,0.03)'"
                @mouseleave="e => (e.currentTarget as HTMLElement).style.background=!n.read?'rgba(14,165,233,0.04)':'transparent'">
                <div :style="{ width:'30px', height:'30px', borderRadius:'8px', background:`${notifColor(n.type)}18`, border:`1px solid ${notifColor(n.type)}30`, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0, color:notifColor(n.type) }">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" :stroke="notifColor(n.type)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" v-html="notifIcon(n.type)" />
                </div>
                <div style="flex:1;min-width:0;">
                  <div style="font-size:12px;font-weight:600;color:#7B92B0;">{{ n.title }}</div>
                  <div style="font-size:11px;color:rgba(100,118,142,0.8);margin-top:2px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;">{{ n.message }}</div>
                </div>
                <div v-if="!n.read" style="width:6px;height:6px;border-radius:50%;background:#0EA5E9;flex-shrink:0;margin-top:4px;" />
              </div>
            </div>
          </div>
        </Transition>
      </div>

      <div style="width:1px;height:20px;background:rgba(255,255,255,0.07);margin:0 6px;" />

      <!-- Usuario -->
      <div style="position:relative;">
        <button @click="userOpen=!userOpen; notifOpen=false"
          :style="{ display:'flex', alignItems:'center', gap:'8px', height:'36px', padding:'0 10px 0 6px', borderRadius:'10px', background:userOpen?'rgba(255,255,255,0.08)':'transparent', border:'1px solid transparent', cursor:'pointer' }"
          @mouseenter="e => (e.currentTarget as HTMLElement).style.background='rgba(255,255,255,0.05)'"
          @mouseleave="e => { if(!userOpen)(e.currentTarget as HTMLElement).style.background='transparent' }">
          <div style="width:28px;height:28px;border-radius:8px;background:linear-gradient(135deg,#0EA5E9,#7DD3FC);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:white;flex-shrink:0;">
            {{ initials }}
          </div>
          <div v-if="!isMobile" style="text-align:left;">
            <div style="font-size:12px;font-weight:600;color:#E2EAF4;line-height:1;">{{ firstName }}</div>
            <div style="font-size:10px;color:rgba(100,118,142,0.8);margin-top:2px;">{{ roleLabel }}</div>
          </div>
          <svg v-if="!isMobile" :width="12" :height="12" viewBox="0 0 24 24" fill="none" stroke="rgba(100,118,142,0.7)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" :style="{ transition:'transform 0.2s', transform:userOpen?'rotate(180deg)':'rotate(0deg)', marginLeft:'2px' }">
            <path d="m6 9 6 6 6-6"/>
          </svg>
        </button>

        <Transition name="dropdown">
          <div v-if="userOpen" style="position:absolute;right:0;top:44px;width:200px;background:#0C1A2E;border:1px solid rgba(255,255,255,0.1);border-radius:14px;box-shadow:0 16px 48px rgba(0,0,0,0.6);overflow:hidden;z-index:50;">
            <div style="padding:12px 14px;border-bottom:1px solid rgba(255,255,255,0.07);">
              <div style="font-size:12px;font-weight:600;color:#E2EAF4;">{{ auth.user?.name }}</div>
              <div style="font-size:11px;color:rgba(100,118,142,0.8);margin-top:2px;">{{ auth.user?.email }}</div>
            </div>
            <div style="border-top:1px solid rgba(255,255,255,0.07);">
              <button @click="handleLogout"
                style="width:100%;display:flex;align-items:center;gap:8px;padding:10px 14px;font-size:12px;color:#EF4444;background:none;border:none;cursor:pointer;text-align:left;font-family:inherit;"
                @mouseenter="e => (e.currentTarget as HTMLElement).style.background='rgba(239,68,68,0.06)'"
                @mouseleave="e => (e.currentTarget as HTMLElement).style.background='transparent'">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                  <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" x2="9" y1="12" y2="12"/>
                </svg>
                Cerrar sesión
              </button>
            </div>
          </div>
        </Transition>
      </div>
    </div>

    <div v-if="notifOpen || userOpen" style="position:fixed;inset:0;z-index:40;" @click="notifOpen=false; userOpen=false" />
  </header>
</template>

<script setup lang="ts">
const auth   = useAuthStore()
const ui     = useUIStore()
const router = useRouter()
const { isMobile } = useBreakpoint()

const notifOpen = ref(false)
const userOpen  = ref(false)

const roleLabels: Record<string, string> = { admin:'Administrador', buyer:'Comprador', approver:'Aprobador', viewer:'Visor' }

const initials  = computed(() => auth.user?.name.split(' ').slice(0,2).map(n=>n[0]).join('') ?? '..')
const firstName = computed(() => auth.user?.name.split(' ').slice(0,2).join(' ') ?? '...')
const roleLabel = computed(() => auth.user ? (roleLabels[auth.user.role] ?? auth.user.role) : '...')

const notifColors: Record<string, string> = { order:'#7DD3FC', approval:'#22C55E', delivery:'#0EA5E9', system:'#94a3b8', alert:'#F59E0B' }
function notifColor(type: string) { return notifColors[type] ?? '#94a3b8' }
function notifIcon(type: string): string {
  if (type === 'order')    return '<path d="M16.5 9.4 7.55 4.24"/><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>'
  if (type === 'approval') return '<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>'
  if (type === 'delivery') return '<rect width="16" height="13" x="1" y="5" rx="1"/><path d="M1 10h16"/><path d="M17 5h2a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-2"/>'
  if (type === 'alert')    return '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/>'
  return '<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/>'
}

async function handleLogout() {
  userOpen.value = false
  await auth.logout()
  router.push('/login')
}
</script>
<template>
  <div style="display:flex; height:100vh; background:#06101E; position:relative; overflow:hidden;">
    <!-- Fondo -->
    <div style="position:fixed;inset:0;pointer-events:none;z-index:0;background:radial-gradient(ellipse 70% 50% at 0% 0%,rgba(14,165,233,0.09) 0%,transparent 60%),radial-gradient(ellipse 50% 40% at 100% 100%,rgba(14,165,233,0.06) 0%,transparent 60%)" />
    <div style="position:fixed;inset:0;pointer-events:none;z-index:0;background-image:linear-gradient(rgba(255,255,255,0.016) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,0.016) 1px,transparent 1px);background-size:64px 64px" />

    <!-- Backdrop mobile -->
    <Transition name="fade">
      <div v-if="isMobile && ui.mobileSidebarOpen"
        style="position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:150;backdrop-filter:blur(2px);"
        @click="ui.closeMobileSidebar()" />
    </Transition>

    <AppSidebar />

    <div style="flex:1;display:flex;flex-direction:column;min-width:0;overflow:hidden;position:relative;z-index:1;">
      <AppHeader />

      <!-- Alerta datos fiscales pendientes -->
      <Transition name="slide-down">
        <div v-if="showFiscalBanner" :style="{ flexShrink:0, padding: isMobile ? '0 16px' : '0 28px' }">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 16px;border-radius:12px;background:linear-gradient(135deg,rgba(245,158,11,0.12),rgba(245,158,11,0.06));border:1px solid rgba(245,158,11,0.3);margin-top:12px;flex-wrap:wrap;gap:10px;">
            <div style="display:flex;align-items:center;gap:10px;">
              <div style="width:32px;height:32px;border-radius:9px;background:rgba(245,158,11,0.15);border:1px solid rgba(245,158,11,0.25);display:flex;align-items:center;justify-content:center;flex-shrink:0;">
                <AlertTriangle :size="15" color="#fbbf24" />
              </div>
              <div>
                <div style="font-size:13px;font-weight:600;color:#fcd34d;">Datos fiscales incompletos</div>
                <div style="font-size:12px;color:rgba(245,158,11,0.8);margin-top:1px;">Completa tu información fiscal para poder recibir facturas (CFDI).</div>
              </div>
            </div>
            <button @click="showFiscalModal=true"
              style="height:34px;padding:0 16px;border-radius:9px;border:none;background:linear-gradient(135deg,#F59E0B,#D97706);color:white;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;white-space:nowrap;flex-shrink:0;">
              Completar ahora
            </button>
          </div>
        </div>
      </Transition>

      <main :style="{ flex:1, overflowY:'auto', padding: isMobile ? '16px 16px 32px' : '28px 28px 40px' }">
        <slot />
      </main>
    </div>
  </div>

  <!-- Modal datos fiscales -->
  <FiscalDataModal v-model="showFiscalModal" :required="fiscalModalRequired" />
</template>

<script setup lang="ts">
import { AlertTriangle } from '@lucide/vue'

const auth = useAuthStore()
const ui   = useUIStore()
const { isMobile } = useBreakpoint()

const needsFiscal = (user: typeof auth.user) => !!user && user.role !== 'admin' && !user.fiscalCompleted

const route = useRoute()
watch(() => route.path, () => { if (isMobile.value) ui.closeMobileSidebar() })

onMounted(async () => {
  if (!auth.loaded) await auth.init()
  if (needsFiscal(auth.user)) showFiscalModal.value = true
  ui.fetchNotifications()
})

const showFiscalModal     = ref(false)
const fiscalModalRequired = computed(() => needsFiscal(auth.user))
const showFiscalBanner    = computed(() => auth.loaded && needsFiscal(auth.user) && !showFiscalModal.value)
</script>

<style>
.fade-enter-active, .fade-leave-active { transition: opacity 0.25s; }
.fade-enter-from, .fade-leave-to { opacity: 0; }
</style>
